oreign_yen\"]\n    foreign_adjusted = foreign_total * adj_factor\n    \n    # Total assets adjusted\n    total_assets = values[\"total_assets\"]\n    total_assets_adjusted = total_assets * adj_factor\n    \n    # Share percentage\n    share_pct = (foreign_adjusted / total_assets_adjusted) * 100\n    \n    results[period] = {\n        \"foreign_total\": foreign_total,\n        \"total_assets\": total_assets,\n        \"adj_factor\": adj_factor,\n        \"foreign_adjusted\": foreign_adjusted,\n        \"total_assets_adjusted\": total_assets_adjusted,\n        \"share_pct\": share_pct\n    }\n    \n    print(f\"\\nPeriod: {period}\")\n    print(f\"  CPI: {cpi_period}, Adjustment factor: {adj_factor:.6f}\")\n    print(f\"  Foreign exchange (original): {foreign_total:,}\")\n    print(f\"  Total assets (original): {total_assets:,}\")\n    print(f\"  Foreign exchange (adj to Mar 2003): {foreign_adjusted:,.0f}\")\n    print(f\"  Total assets (adj to Mar 2003): {total_assets_adjusted:,.0f}\")\n    print(f\"  Share %: {share_pct:.6f}%\")\n\n# Now compute averages for the two sets\n# June periods (end of June for 2000, 2001, 2002)\njune_periods = [\"2000-06\", \"2001-06\", \"2002-06\"]\n# September periods\nsept_periods = [\"2000-09\", \"2001-09\", \"2002-09\"]\n\njune_shares = [results[p][\"share_pct\"] for p in june_periods]\nsept_shares = [results[p][\"share_pct\"] for p in sept_periods]\n\njune_avg = sum(june_shares) / len(june_shares)\nsept_avg = sum(sept_shares) / len(sept_shares)\n\nprint(\"\\n\" + \"=\"*60)\nprint(\"SUMMARY\")\nprint(\"=\"*60)\nprint(f\"\\nJune periods ({june_periods}):\")\nfor p in june_periods:\n    print(f\"  {p}: {results[p]['share_pct']:.6f}%\")\nprint(f\"  Average: {june_avg:.6f}%\")\n\nprint(f\"\\nSeptember periods ({sept_periods}):\")\nfor p in sept_periods:\n    print(f\"  {p}: {results[p]['share_pct']:.6f}%\")\nprint(f\"  Average: {sept_avg:.6f}%\")\n\nabs_diff = abs(june_avg - sept_avg)\nprint(f\"\\nAbsolute difference: {abs_diff:.6f} perce